async def act(page):
    # Navigate directly to the Shipping Address edit page (use the second Edit link seen on the order view).
    # This avoids clicking a link that would navigate away from the current page as the last action.
    await page.goto('/index.php/admin/sales_order/address/address_id/591/')
    await page.wait_for_load_state('networkidle')

    # Attempt to close a blocking popup if present (common modal close variants).
    for close_name in ["Close", "×", "Close (Esc)", "close"]:
        try:
            btn = page.get_by_role("button", name=close_name)
            if await btn.count() > 0:
                await btn.first.click()
                # allow UI to settle
                await page.wait_for_timeout(300)
                break
        except Exception:
            pass

    # Helper to try multiple label variants for text inputs
    async def fill_by_labels(labels, value):
        for lbl in labels:
            try:
                locator = page.get_by_label(lbl)
                if await locator.count() > 0:
                    await locator.first.fill(value)
                    return True
            except Exception:
                pass
        # Fallback to textbox role by name
        for lbl in labels:
            try:
                tb = page.get_by_role("textbox", name=lbl)
                if await tb.count() > 0:
                    await tb.first.fill(value)
                    return True
            except Exception:
                pass
        return False

    # Helper to select combobox / select elements
    async def select_combo_by_names(names, label_to_choose, value_fallback=None):
        for nm in names:
            try:
                combo = page.get_by_role("combobox", name=nm)
                if await combo.count() > 0:
                    try:
                        await combo.first.select_option(label=label_to_choose)
                    except Exception:
                        if value_fallback is not None:
                            await combo.first.select_option(value=value_fallback)
                    return True
            except Exception:
                pass
        # Try top-level selects by label
        for nm in names:
            try:
                sel = page.get_by_label(nm)
                if await sel.count() > 0:
                    try:
                        await sel.first.select_option(label=label_to_choose)
                    except Exception:
                        if value_fallback is not None:
                            await sel.first.select_option(value=value_fallback)
                    return True
            except Exception:
                pass
        return False

    # Desired values
    street_value = "456 Oak Avenue, Apartment 5B"
    city_value = "New York"
    postcode_value = "10001"
    region_label = "New York"
    region_value = "NY"
    country_label = "United States"
    country_value = "US"

    # Fill street (Magento may present multiple street lines; fill the first matching control)
    street_labels = ["Street Address", "Street", "Address", "Street 1", "Street 0"]
    await fill_by_labels(street_labels, street_value)

    # Fill city
    city_labels = ["City", "City/Town"]
    await fill_by_labels(city_labels, city_value)

    # Fill postcode / ZIP
    postcode_labels = ["ZIP/Postal Code", "Zip / Postal Code", "ZIP", "Postcode", "Postal Code"]
    await fill_by_labels(postcode_labels, postcode_value)

    # Select region/state
    region_names = ["State/Province", "Region", "Region/State", "State"]
    await select_combo_by_names(region_names, region_label, region_value)

    # Select country
    country_names = ["Country", "Country/Region"]
    await select_combo_by_names(country_names, country_label, country_value)

    # Try to click a Save button on the address edit form. Prefer "Save Address" then common alternatives.
    for name in ["Save Address", "Save", "Save Changes", "Submit"]:
        try:
            btn = page.get_by_role("button", name=name)
            if await btn.count() > 0:
                await btn.first.click()
                return
        except Exception:
            pass
        try:
            lnk = page.get_by_role("link", name=name)
            if await lnk.count() > 0:
                await lnk.first.click()
                return
        except Exception:
            pass

    # Final fallback: try any button with text 'Save'
    try:
        generic_save = page.get_by_role("button").filter(has=page.get_by_text("Save"))
        if await generic_save.count() > 0:
            await generic_save.first.click()
            return
    except Exception:
        pass

    # If no save control found, raise so the harness knows the update couldn't be completed.
    raise Exception("Unable to find a Save control on the address edit page for order #299")
